using System.Text.Json.Nodes;
using System.Windows;
using Microsoft.Win32;
namespace ArchiveReader;
public partial class ResearchBundleWindow:Window
{
 readonly Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker;bool busy;
 static string T(string value)=>Localizer.Text(value);
 public ResearchBundleWindow(Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker){this.worker=worker;InitializeComponent();Localizer.Apply(this,Localizer.Language);Closing+=(_,e)=>{if(busy)e.Cancel=true;};Loaded+=async(_,_)=>{if(!Environment.GetCommandLineArgs().Contains("--smoke-bundle"))return;await Run(async()=>{Weights.IsChecked=true;PreviewReport.Text=Report(await Call("bundle_preview",Options()));Tabs.IsEnabled=true;SmokeCapture.Save(this,"bundle-ui","tab-0.png");var root=Environment.GetEnvironmentVariable("ARCHIVEREADER_DATA")!;var name="smoke-bundle-"+Guid.NewGuid().ToString("N");Package.Text=System.IO.Path.Combine(root,name+".zip");Destination.Text=System.IO.Path.Combine(root,name+"-restored");var options=Options();options["path"]=Package.Text;await Call("bundle_create",options);RestoreReport.Text=Report(await Call("bundle_inspect",new(){["path"]=Package.Text}));var result=await Call("bundle_restore",new(){["path"]=Package.Text,["destination"]=Destination.Text});RestoreReport.Text=result["destination"]+"\n\n"+Report(result);Tabs.SelectedIndex=1;Tabs.IsEnabled=true;SmokeCapture.Save(this,"bundle-ui","tab-1.png");});Close();};}
 Task<JsonNode> Call(string command,JsonObject args)=>worker(command,args,default);
 JsonObject Options()=>new(){["include_models"]=Weights.IsChecked==true,["model_paths"]=new JsonArray(ModelPaths.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).Select(p=>JsonValue.Create(p)).ToArray())};
 async Task Run(Func<Task> action){if(busy)return;busy=true;Tabs.IsEnabled=false;Status.Text=T("Перевірка та копіювання можуть тривати довго.");try{await action();Status.Text=T("Завершено");}catch(Exception ex){Status.Text=T(ex.Message);}finally{busy=false;Tabs.IsEnabled=true;}}
 static string Report(JsonNode result)=>T("Файлів")+": "+result["files"]+"\n"+T("Документів")+": "+result["documents"]+"\n"+T("Розмір")+": "+((result["bytes"]?.GetValue<long>()??0)/1048576.0).ToString("F1")+" MB\n\n"+T("Додані моделі")+":\n"+string.Join("\n",(result["models"] as JsonArray??new()).Where(m=>m?["included_path"]!=null).Select(m=>m!["original_path"]!.ToString()))+"\n\n"+T("Відсутні моделі")+":\n"+string.Join("\n",(result["missing_models"] as JsonArray??new()).Select(m=>m!.ToString()))+"\n\n"+T("Моделі без вкладених файлів")+":\n"+string.Join("\n",result["excluded_models"] is JsonArray excluded?excluded.Select(m=>m!.ToString()):(result["models"] as JsonArray??new()).Where(m=>m?["included_path"]==null).Select(m=>m!["original_path"]!.ToString()));
 async void Preview(object sender,RoutedEventArgs e)=>await Run(async()=>PreviewReport.Text=Report(await Call("bundle_preview",Options())));
 async void Create(object sender,RoutedEventArgs e){var dialog=new SaveFileDialog{Filter="ZIP|*.zip",FileName="ArchiveReader-research.zip",OverwritePrompt=true};if(dialog.ShowDialog()!=true)return;await Run(async()=>{var options=Options();options["path"]=dialog.FileName;var result=await Call("bundle_create",options);PreviewReport.Text=result["path"]+"\n\n"+Report(result);});}
 void Choose(object sender,RoutedEventArgs e){var dialog=new OpenFileDialog{Filter="ZIP|*.zip"};if(dialog.ShowDialog()==true){Package.Text=dialog.FileName;Destination.Text=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(dialog.FileName)!,"ArchiveReader-restored-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));}}
 async void Inspect(object sender,RoutedEventArgs e)=>await Run(async()=>RestoreReport.Text=Report(await Call("bundle_inspect",new(){["path"]=Package.Text})));
 async void Restore(object sender,RoutedEventArgs e)=>await Run(async()=>{var result=await Call("bundle_restore",new(){["path"]=Package.Text,["destination"]=Destination.Text});RestoreReport.Text=result["destination"]+"\n\n"+Report(result)+"\n\n"+T("Старі черги розпізнавання після перенесення створіть заново. Невкладені моделі встановіть окремо.");});
}
